var i=`0560-uzbek-plov`;var t=`world-0560`;var n=`UZ`;var r=`central-asia`;var o=4;var l=111;var s={en:`Uzbek Plov`,ua:`Узбецький плов`};var d={en:`A traditional dish from Uzbekistan, centered on lamb, yellow onion, carrot, garlic. A measured home-kitchen version organized by cooking step. Uzbek plov adapted with basmati rice; traditional regional devzira rice is unavailable in the catalog.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: ягнятина, жовта цибуля, морква, часник. Домашній варіант із кількостями продуктів за етапами приготування. Узбецький плов адаптовано під басматі, оскільки традиційного рису девзіра немає в каталозі.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`lamb`,700,`g`],[`sunflower-oil`,110,`ml`],[`yellow-onion`,250,`g`]]},{en:`Cook the julienned carrots with the lamb, onion, cumin and garlic to form the richly flavored plov base called zirvak.`,ua:`Готуйте нарізану соломкою моркву з бараниною, цибулею, зірою й часником до утворення ароматної основи плову, зірваку.`,t:[`stewing`],m:55,i:[[`carrot`,650,`g`],[`cumin-seeds`,8,`g`],[`garlic`,2,`clove`],[`water`,650,`ml`]]},{en:`Rinse rice thoroughly and spread over the zirvak in a level layer without stirring; add measured hot water and cook until absorbed.`,ua:`Добре промийте рис і розкладіть рівним шаром поверх зірваку, не перемішуючи; долийте відміряну гарячу воду та готуйте до її поглинання.`,t:[`pilaf-method`],m:27,i:[[`basmati-rice`,530,`g`],[`water`,300,`ml`]]},{en:`Take off the heat and let the rice rest under a clean towel or lid for about 15 minutes before serving.`,ua:`Зніміть із вогню та дайте рису відпочити під чистим рушником або кришкою приблизно 15 хвилин перед подаванням.`,t:[`rice-resting`,`fluffing-grains`],m:15,i:[]}];var u={slug:i,id:t,country:`UZ`,region:r,servings:4,minutes:111,title:s,text:d,steps:c};export{n as country,u as default,t as id,l as minutes,r as region,o as servings,i as slug,c as steps,d as text,s as title};